with feeders as (
    select
        md5(upper('HUB_ORG_UNIT|' || (HUB_ORG_UNIT_BK__CONTROLLING_OFFICE))) as HUB_ORG_UNIT_HK
        , cast(null as varchar) as ZONE_NAME
        , CONTROLLING_OFFICE as ORG_UNIT_NAME
        , OPERATING_CODE as ORG_UNIT_CODE
        , cast(null as varchar) as BRANCH_TYPE
        , cast(null as varchar) as PARENT_ORG_UNIT_REFERENCE
        , cast(null as varchar) as ORG_UNIT_STATUS
        , cast(null as varchar) as HEAD_REFERENCE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(CONTROLLING_OFFICE),'')) is not null
    union all
    select
        md5(upper('HUB_ORG_UNIT|' || (HUB_ORG_UNIT_BK__BRANCH_CODE))) as HUB_ORG_UNIT_HK
        , PRINT_ZONE as ZONE_NAME
        , BRANCH_NAME as ORG_UNIT_NAME
        , cast(null as varchar) as ORG_UNIT_CODE
        , BRANCH_TYPE as BRANCH_TYPE
        , PARENT_BRANCH_CODE as PARENT_ORG_UNIT_REFERENCE
        , ACT_INACT_STATUS as ORG_UNIT_STATUS
        , BM_USERNAME as HEAD_REFERENCE
        , 'BJAZ_BRANCH_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_branch_master') }}
    where (nullif(trim(BRANCH_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_ORG_UNIT|' || (HUB_ORG_UNIT_BK__DEPARTMENT_CODE))) as HUB_ORG_UNIT_HK
        , cast(null as varchar) as ZONE_NAME
        , DM_LOCATION as ORG_UNIT_NAME
        , cast(null as varchar) as ORG_UNIT_CODE
        , cast(null as varchar) as BRANCH_TYPE
        , cast(null as varchar) as PARENT_ORG_UNIT_REFERENCE
        , cast(null as varchar) as ORG_UNIT_STATUS
        , cast(null as varchar) as HEAD_REFERENCE
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(DEPARTMENT_CODE),'')) is not null
),

resolved as (
    select
        HUB_ORG_UNIT_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ZONE_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ZONE_NAME end)) as ZONE_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ORG_UNIT_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ORG_UNIT_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ORG_UNIT_NAME end)) as ORG_UNIT_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ORG_UNIT_CODE end) as ORG_UNIT_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then BRANCH_TYPE end) as BRANCH_TYPE,
        max(case when SOURCE_RUN = 'opus_health_v2' then PARENT_ORG_UNIT_REFERENCE end) as PARENT_ORG_UNIT_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ORG_UNIT_STATUS end) as ORG_UNIT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_REFERENCE end) as HEAD_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ORG_UNIT_HK
),

hashed as (
    select
        *,
        case when ZONE_NAME is not null or ORG_UNIT_NAME is not null or ORG_UNIT_CODE is not null or BRANCH_TYPE is not null or PARENT_ORG_UNIT_REFERENCE is not null or ORG_UNIT_STATUS is not null or HEAD_REFERENCE is not null
                     then md5(upper(coalesce(cast(ZONE_NAME as varchar), '') || '|' || coalesce(cast(ORG_UNIT_NAME as varchar), '') || '|' || coalesce(cast(ORG_UNIT_CODE as varchar), '') || '|' || coalesce(cast(BRANCH_TYPE as varchar), '') || '|' || coalesce(cast(PARENT_ORG_UNIT_REFERENCE as varchar), '') || '|' || coalesce(cast(ORG_UNIT_STATUS as varchar), '') || '|' || coalesce(cast(HEAD_REFERENCE as varchar), '')))
                end as SAT_ORG_UNIT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_ORG_UNIT_HK is not null
  and SAT_ORG_UNIT_DEFINITION_HASHDIFF is not null
